const std = @import("std");

pub fn main() !void {
    const s1 = "listen";
    const s2 = "silent";

    var counts: [26]u8 = [_]u8{0} ** 26;

    for (s1) |ch| counts[ch - 'a'] += 1;
    for (s2) |ch| counts[ch - 'a'] -|= 1;

    var is_anagram = true;
    for (counts) |c| {
        if (c != 0) { is_anagram = false; break; }
    }

    std.debug.print("\"{} \" and \"{} \" ", .{s1, s2});
    if (is_anagram) {
        std.debug.print("are anagrams\n", .{});
    } else {
        std.debug.print("are not anagrams\n", .{});
    }
}
